test('addLine adds a new line at the end', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const r = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(r.value.lines[1].qty, 3);
  assert.equal(r.value.lines[1].name, 'Development (hour)');
  assert.equal(r.value.lines[1].unitPrice, 9500);
});

test('addLine increases qty if SKU already exists', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const r = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[0].qty, 5);
});

test('addLine preserves other line data when increasing qty', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  }).value;

  const r = addLine(invoice, { sku: 'DES-HOUR', qty: 1 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].qty, 3);
  assert.equal(r.value.lines[1].qty, 3);
});

test('addLine reports NOT_DRAFT if invoice is not draft', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  invoice.status = 'sent';

  const r = addLine(invoice, { sku: 'DEV-HOUR', qty: 1 });
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('addLine reports NOT_DRAFT for null invoice', () => {
  const r = addLine(null, { sku: 'DES-HOUR', qty: 1 });
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('addLine reports QTY_INVALID for invalid quantity', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  assert.deepEqual(
    addLine(invoice, { sku: 'DEV-HOUR', qty: 0 }),
    { ok: false, error: 'QTY_INVALID' }
  );
  assert.deepEqual(
    addLine(invoice, { sku: 'DEV-HOUR', qty: -5 }),
    { ok: false, error: 'QTY_INVALID' }
  );
  assert.deepEqual(
    addLine(invoice, { sku: 'DEV-HOUR', qty: 2.5 }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('addLine reports UNKNOWN_SKU for invalid SKU', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const r = addLine(invoice, { sku: 'NOPE', qty: 1 });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine does not mutate original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;
  const invoiceCopy = JSON.parse(JSON.stringify(invoice));

  addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.deepEqual(invoice, invoiceCopy);
});

test('removeLine removes a line by SKU', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  }).value;

  const r = removeLine(invoice, 'DES-HOUR');
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'DEV-HOUR');
});

test('removeLine preserves other line data', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 3 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  }).value;

  const r = removeLine(invoice, 'DEV-HOUR');
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[0].qty, 2);
  assert.equal(r.value.lines[1].sku, 'LOGO-PACK');
  assert.equal(r.value.lines[1].qty, 1);
});

test('removeLine reports NOT_DRAFT if invoice is not draft', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  invoice.status = 'sent';

  const r = removeLine(invoice, 'DES-HOUR');
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine reports NOT_DRAFT for null invoice', () => {
  const r = removeLine(null, 'DES-HOUR');
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine reports LINE_NOT_FOUND if SKU not on invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const r = removeLine(invoice, 'DEV-HOUR');
  assert.deepEqual(r, { ok: false, error: 'LINE_NOT_FOUND' });
});

test('removeLine reports NO_LINES if removing the last line', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const r = removeLine(invoice, 'DES-HOUR');
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('removeLine does not mutate original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  }).value;
  const invoiceCopy = JSON.parse(JSON.stringify(invoice));

  removeLine(invoice, 'DES-HOUR');
  assert.deepEqual(invoice, invoiceCopy);
});

